import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
// Niveaux pour le profil simple de l'étudiant
const NIVEAUX_ETUDIANT = ['Primaire', 'Collège 1ère', 'Collège 2ème', 'Collège 3ème', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université L1', 'Université L2', 'Université L3', 'Master'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [structure, setStructure] = useState([]); // Domaines > Niveaux > Matières
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  // Modales
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    fetchProfileData();
  }, [user]);

  const fetchProfileData = async () => {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      const res = await api.get(route);
      setForm(res.data);

      if (user?.role === 'professeur') {
        // RÉCUPÉRATION DE LA STRUCTURE ADMIN (CASCADE)
        const resStruct = await api.get('/api/admin/referentiel/structure');
        setStructure(resStruct.data);
      }
      setLoading(false);
    } catch (e) {
      console.error("Erreur chargement profil");
      setLoading(false);
    }
  };

  // --- 1. GESTION PHOTO ---
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setForm({ ...form, photo_url: res.data.url });
      alert("✅ Photo mise à jour !");
    } catch (e) { alert("Erreur upload photo"); }
  };

  // --- 2. GESTION CERTIFICATS ---
  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('description', newCert.description);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setShowCertModal(false);
      fetchProfileData();
    } catch (e) { alert("Erreur upload certificat"); }
  };

  // --- 3. LOGIQUE CASCADE : MATIÈRES & TARIFS ---

  // Vérifie si une matière est sélectionnée pour un niveau précis
  const isSelected = (matId, nivId) => {
    return form.tarifs_matieres?.some(t => t.matiere_id === matId && t.niveau_id === nivId);
  };

  // Récupère le tarif actuel pour un couple
  const getTarif = (matId, nivId) => {
    const item = form.tarifs_matieres?.find(t => t.matiere_id === matId && t.niveau_id === nivId);
    return item ? item.tarif : '';
  };

  const handleToggleMatiere = (matId, nivId) => {
    let updated = [...(form.tarifs_matieres || [])];
    if (isSelected(matId, nivId)) {
      updated = updated.filter(t => !(t.matiere_id === matId && t.niveau_id === nivId));
    } else {
      updated.push({ matiere_id: matId, niveau_id: nivId, tarif: 20 }); // Prix par défaut
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handlePriceChange = (matId, nivId, price) => {
    const updated = form.tarifs_matieres.map(t => 
      (t.matiere_id === matId && t.niveau_id === nivId) ? { ...t, tarif: parseFloat(price) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  // --- 4. SAUVEGARDE ---
  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        niveau: form.niveau,
        telephone: form.telephone,
        bio: form.bio,
        // On envoie la liste des triplets au Backend
        tarifs_complets: form.tarifs_matieres 
      };
      await api.put(route, payload);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  if (loading) return <div style={{padding: 50, textAlign: 'center'}}>Chargement...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* HEADER PROFIL */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 110, height: 110, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 5, right: 5, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.8rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)' }}>{form.email} • <span style={{ color: 'var(--accent)' }}>{user?.role}</span></p>
          {user?.role === 'professeur' && (
            <span style={{ background: form.statut_validation === 'validé' ? 'rgba(67,233,123,0.15)' : 'rgba(255,101,132,0.15)', color: form.statut_validation === 'validé' ? '#43e97b' : '#ff6584', padding: '4px 12px', borderRadius: 20, fontSize: '.75rem', fontWeight: 700, marginTop: 8, display: 'inline-block' }}>
              {form.statut_validation?.toUpperCase()}
            </span>
          )}
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '400px 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE INFOS PERSO */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20, fontSize: '1.1rem' }}>👤 Informations personnelles</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 15 }}>
               <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                  <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Prénom</label><input style={inp} value={form.user_prenom || ''} onChange={e => setForm({...form, user_prenom: e.target.value})} /></div>
                  <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Nom</label><input style={inp} value={form.user_nom || ''} onChange={e => setForm({...form, user_nom: e.target.value})} /></div>
               </div>
               <div>
                  <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Ville</label>
                  <select style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})}>
                    <option value="">Choisir...</option>
                    {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
               </div>
               {user?.role === 'étudiant' && (
                <div>
                  <label style={{fontSize:'.75rem', color:'var(--text2)'}}>Niveau d'études</label>
                  <select style={inp} value={form.niveau || ''} onChange={e => setForm({...form, niveau: e.target.value})}>
                    <option value="">Choisir...</option>
                    {NIVEAUX_ETUDIANT.map(n => <option key={n} value={n}>{n}</option>)}
                  </select>
                </div>
               )}
               <div><label style={{fontSize:'.75rem', color:'var(--text2)'}}>Téléphone</label><input style={inp} value={form.telephone || ''} onChange={e => setForm({...form, telephone: e.target.value})} /></div>
               <button onClick={handleSave} style={{ width: '100%', background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, cursor: 'pointer', marginTop: 10 }}>
                  {saved ? '✅ Mis à jour' : 'Enregistrer les infos'}
               </button>
            </div>
          </div>

          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
                <h3 style={{ marginBottom: 16 }}>📜 Diplômes</h3>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 10, borderRadius: 12, border: '1px solid var(--border)', fontSize: '.8rem' }}>
                            <div style={{ fontWeight: 600 }}>{c.titre}</div>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)' }}>Voir PDF</a>
                        </div>
                    ))}
                    <div onClick={() => setShowCertModal(true)} style={{ border: '2px dashed var(--border)', borderRadius: 12, padding: 15, cursor: 'pointer', textAlign: 'center', color: 'var(--accent)', fontSize: '.8rem' }}>+ Ajouter</div>
                </div>
            </div>
          )}
        </div>

        {/* COLONNE MATIÈRES (CASCADE DESIGN) */}
        {user?.role === 'professeur' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
              <h3 style={{ marginBottom: 20 }}>📚 Mes Enseignements & Tarifs</h3>

              {structure.map(domaine => (
                <div key={domaine.id} style={{ marginBottom: 32 }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: 10, color: 'var(--accent)', fontWeight: 800, fontSize: '1.1rem', marginBottom: 16, borderBottom: '1px solid var(--border)', paddingBottom: 8 }}>
                    📂 {domaine.nom}
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: 20, marginLeft: 10 }}>
                    {domaine.niveaux?.map(niveau => (
                      <div key={niveau.id} style={{ background: 'var(--surface2)', padding: 16, borderRadius: 16, border: '1px solid var(--border)' }}>
                        <div style={{ fontWeight: 700, marginBottom: 12, fontSize: '.9rem', color: 'var(--text)' }}>🎓 {niveau.nom}</div>

                        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                          {niveau.matieres?.map(matiere => {
                            const selected = isSelected(matiere.id, niveau.id);
                            return (
                              <div key={matiere.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', background: selected ? 'rgba(108,99,255,0.05)' : 'var(--card)', padding: '8px 12px', borderRadius: 10, border: selected ? '1px solid var(--accent)' : '1px solid transparent' }}>
                                <label style={{ display: 'flex', alignItems: 'center', gap: 8, fontSize: '.85rem', cursor: 'pointer' }}>
                                  <input 
                                    type="checkbox" 
                                    checked={selected} 
                                    onChange={() => handleToggleMatiere(matiere.id, niveau.id)} 
                                  />
                                  {matiere.nom}
                                </label>
                                {selected && (
                                  <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                                    <input 
                                      type="number" 
                                      value={getTarif(matiere.id, niveau.id)} 
                                      onChange={(e) => handlePriceChange(matiere.id, niveau.id, e.target.value)}
                                      style={{ width: 55, background: 'var(--bg)', border: '1px solid var(--border)', color: '#fff', textAlign: 'center', borderRadius: 6, padding: '2px' }} 
                                    />
                                    <span style={{ fontSize: '.7rem', fontWeight: 700 }}>DT</span>
                                  </div>
                                )}
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              ))}

              <button onClick={handleSave} style={{ width: '100%', background: 'linear-gradient(135deg,#6c63ff,#ff6584)', color: '#fff', border: 'none', padding: 16, borderRadius: 15, fontWeight: 700, fontSize: '1rem', cursor: 'pointer', marginTop: 20 }}>
                Enregistrer mon catalogue de cours
              </button>
            </div>
          </div>
        )}
      </div>

      {/* MODALE CERTIFICAT */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: 'var(--surface)', padding: 30, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
                <h3 style={{ marginBottom: 20 }}>Ajouter un diplôme</h3>
                <form onSubmit={handleCertUpload}>
                    <input style={{...inp, marginBottom: 15}} placeholder="Titre (ex: Master en Physique)" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    <textarea style={{...inp, marginBottom: 15, height: 80}} placeholder="Description" onChange={e => setNewCert({...newCert, description: e.target.value})} />
                    <input type="file" style={{marginBottom: 20, color: 'white'}} onChange={e => setSelectedFile(e.target.files[0])} required />
                    <div style={{ display: 'flex', gap: 10 }}>
                        <button type="submit" style={{ flex: 1, background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 12, fontWeight: 600 }}>Sauvegarder</button>
                        <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 12 }}>Annuler</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
